{"command": "cd /home/zhaodan/work/NodeJsProjects/agent-hub-web && python3 - <<'EOF'
import re,glob,json

def extract(path):
    src=open(path).read()
    out=[]
    for m in re.finditer(r"apiClient\.(get|post|put|patch|delete)\b", src):
        method=m.group(1).upper()
        rest=src[m.end():m.end()+400]
        # skip generic type args until first quote
        q=re.search(r"[`'\"]", rest)
        if not q: continue
        quote=q.group(0); start=m.end()+q.start()
        # find matching quote (no escapes handling heavy)
        end=src.find(quote, start+1)
        while end!=-1 and src[end-1]=='\\':
            end=src.find(quote, end+1)
        if end==-1: continue
        p=src[start+1:end]
        if not p.startswith('/'): continue
        norm=re.sub(r"\$\{[^}]+\}","{p}",p)
        norm=norm.split('?')[0]
        out.append((method,norm,p,src[:start].count('\n')+1,path))
    return out

calls=[]
for f in sorted(glob.glob('src/api/*.ts')):
    calls+=extract(f)
print("calls:",len(calls))
for c in calls: print(c[0],c[1],f"({c[4]}:{c[3]})")

# backend
d=json.load(open('/home/zhaodan/work/PythonProjects/agent-hub/docs/openapi.json'))
ops=set()
for p,ms in d['paths'].items():
    pp=p.replace('/api/v1','')
    for m in ms:
        if m in ('get','post','put','patch','delete'):
            ops.add((m.upper(),pp))

def canon(m,p):
    p=re.sub(r"\{[^}]+\}","{p}",p)
    return (m,p)

fcalls={(c[0],canon(c[0],c[1])[1]) for c in calls}
fset=set()
for m,p in fcalls: fset.add((m,p))
print("\n== backend ops not called by frontend ==")
for m,p in sorted(ops-fset): print(f"  {m:6} {p}")
print("\n== frontend calls not in backend openapi ==")
for m,p in sorted(fset-ops): print(f"  {m:6} {p}")
EOF", "description": "对比前端调用与后端 OpenAPI 端点"}

