import re,glob,json

def canon(m,p):
    p=p.split('?')[0]
    p=re.sub(r"\$\{[^}]+\}","{x}",p)
    p=re.sub(r"\{[^}]+\}","{x}",p)
    p=re.sub(r"/+$","",p)
    if not p.startswith('/'): p='/'+p
    return (m.upper(),p)

