import re,html,glob,os
def zh(s):
    return re.findall(r'[\u4e00-\u9fa5][\u4e00-\u9fa5A-Za-z0-9·（）()/%．.\-—…：:；;、\s]{1,30}',s)
def clean(x): return html.unescape(re.sub(r'<[^>]+>',' ',x))
def text_of(path):
    s=open(path,encoding='utf-8').read()
    s=re.sub(r'<script[\s\S]*?</script>','',s)
    s=re.sub(r'<style[\s\S]*?</style>','',s)
    return clean(s)
proto_files={'chat':'docs/prototypes/ui-v7.html','pages':'docs/prototypes/ui-v7-pages.html','admin':'docs/prototypes/ui-v8-admin.html'}
pt={}
for k,f in proto_files.items():
    t=text_of(f)
    toks=[x.strip() for x in zh(t)]
    pt[k]={x for x in toks if len(x)>=2 and not re.fullmatch(r'[\d\s.:%]+',x)}
# frontend text
front={}
for f in glob.glob('src/**/*.vue',recursive=True)+glob.glob('src/**/*.ts',recursive=True):
    try: s=open(f,encoding='utf-8').read()
    except: continue
    if '.spec.' in f or '/__tests__/' in f: continue
    name=f
    for x in zh(s):
        x=x.strip()
        if len(x)>=2: front.setdefault(x,set()).add(name)
print("proto tokens:",{k:len(v) for k,v in pt.items()},"front tokens:",len(front))
for k in ['chat','pages','admin']:
    miss=[x for x in pt[k] if x not in front]
    print(f"\n== {k}: {len(miss)} prototype tokens not found in src ==")
    print(" | ".join(sorted(miss)[:200]))
EOF", "description": "对比原型文案与前端实现文案"}

